```python
class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        if amount > 0:
            self.balance += amount
            print(f"Deposit successful. Balance: {self.balance}")
        else:
            print("Deposit amount must be positive.")

    def withdraw(self, amount):
        if amount > 0 and self.balance >= amount:
            self.balance -= amount
            print(f"Withdrawal successful. Balance: {self.balance}")
        else:
            print("Insufficient funds or withdrawal amount is negative.")

    def check_balance(self):
        print(f"Balance: {self.balance}")


# Example usage:
accounts = [BankAccount(), BankAccount(), BankAccount()]

while True:
    transaction = input("Enter transaction (deposit, withdraw, check balance, exit): ").lower()

    if transaction == "exit":
        break
    elif transaction == "deposit":
        amount = float(input("Enter deposit amount: "))
        accounts[int(input("Enter account number: ")) - 1].deposit(amount)
    elif transaction == "withdraw":
        amount = float(input("Enter withdrawal amount: "))
        accounts[int(input("Enter account number: ")) - 1].withdraw(amount)
    elif transaction == "check balance":
        accounts[int(input("Enter account number: ")) - 1].check_balance()
    else:
        print("Invalid transaction. Please try again.")
```

This program allows you to manage multiple bank accounts and perform transactions as needed. You can add more bank accounts and transaction types as needed.
